from __future__ import annotations

from pathlib import Path
from typing import Any

from menai import Menai, MenaiBytes, MenaiValue

from menai_benchmark import BenchmarkCase, BenchmarkSuite, Implementation

_SUITE_DIR = Path(__file__).resolve().parent
_FIXTURES_DIR = _SUITE_DIR / "fixtures"

# Fixtures are generated by generate_fixtures.py and committed so every run
# reads byte-identical inputs.
_FIXTURE_NAMES = [
    "text-4k.deflate",
    "text-32k.deflate",
    "incremental-16k.deflate",
    "stored-8k.deflate",
    "runs-32k.deflate",
]

_ITERATIONS = 5

_EXPR = '(let ((inflate (import "inflate"))) ((dict-get inflate "inflate") input-data))'


class Suite(BenchmarkSuite):
    """Benchmark suite for the Menai raw DEFLATE decompressor."""

    name = "inflate"
    description = "Decompress raw DEFLATE streams of varying content and block encoding."

    def cases(self) -> list[BenchmarkCase]:
        """Return one case per fixture file."""
        return [
            BenchmarkCase(
                name=name.removesuffix(".deflate"),
                input=_FIXTURES_DIR / name,
                iterations=_ITERATIONS,
            )
            for name in _FIXTURE_NAMES
        ]

    def implementation(self, menai: Menai) -> Implementation:
        """Return the Menai inflate implementation."""
        def prepare_menai(fixture_path: Path) -> Any:
            """Compile the inflate expression and bind the fixture bytes (untimed)."""
            code = menai.compile(_EXPR)
            bindings: dict[str, MenaiValue] = {"input-data": MenaiBytes(fixture_path.read_bytes())}
            return (code, bindings)

        def run_menai(prepared: tuple[Any, dict[str, MenaiValue]]) -> Any:
            """Execute the pre-compiled bytecode with the fixture binding (timed)."""
            code, bindings = prepared
            return menai.vm.execute(code, bindings)

        return Implementation(run=run_menai, prepare=prepare_menai)
